Method.Source:
/// <summary>
/// DebuC 12.12.24
/// </summary>
public void postBuild()
{
    super();

    excelFileIdDialogField = this.bindInfo().getDialogField(this.dataContractObject(), 
        methodStr(NDXExcelPriceJournalImportContract, parmExcelFileId));

    excelFileIdDialogField.registerOverrideMethod(methodStr(FormStringControl, lookup),
        methodStr(NDXExcelPriceJournalImportUIBuilder, lookupExcelFileId), this);
}

/// <summary>
/// DebuC 12.12.24
/// </summary>
/// <param name = "_formStringControl">FormStringControl</param>
private void lookupExcelFileId(FormStringControl _formStringControl)
{

    Query                   query = new Query();
    QueryBuildDataSource    qbds;
    SysTableLookup          sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(NDXExcelTable), _formStringControl);

    qbds = query.addDataSource(tableNum(NDXExcelTable));

    sysTableLookup.addLookupfield(fieldNum(NDXExcelTable, FileId), true);
    sysTableLookup.addLookupfield(fieldNum(NDXExcelTable, FileName));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelTable, AccountRelation));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelTable, Relation));
    sysTableLookup.addLookupfield(fieldNum(NDXExcelTable, RelationType));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
